const row = $input.first().json;

let intake = row.raw_intake || {};
let documents = row.documents || [];

if (typeof intake === "string") {
  intake = JSON.parse(intake);
}

if (typeof documents === "string") {
  documents = JSON.parse(documents);
}

if (!Array.isArray(documents)) {
  documents = [];
}

function firstArrayValue(value) {
  if (Array.isArray(value)) return value[0] || null;
  return value || null;
}

function dateStart(value) {
  if (!value) return null;
  if (typeof value === "object" && value.start) return value.start;
  return value;
}

function cleanText(value) {
  if (!value) return "";
  return String(value).trim();
}

const context = {
  run_id: row.run_id,
  project_id: row.project_page_id,
  intake_page_id: row.intake_page_id,

  project: {
    requester_name: intake["Your name"] || null,
    respondent: intake["Respondent"] || null,
    department: intake["Your department"] || null,
    priority: firstArrayValue(intake["Priority"]),
    preferred_communication: firstArrayValue(intake["Preferred Communication"]),
    deadline: dateStart(intake["Deadline"]),
    submission_time: intake["Submission time"] || null,

    requested_solution: cleanText(intake["What do you need help with?"]),
    business_problem: cleanText(intake["Main business problem"]),
    definition_of_done: cleanText(intake["Definition of Done"]),
    success_metrics: cleanText(
      intake["What would 'success' look like in 3 months? Please provide a specific metric"]
    )
  },

  sources: {
    sop: [],
    documentation: [],
    screenshots: []
  },

  document_index: [],

  stats: {
    total_files: documents.length,
    sop_count: 0,
    documentation_count: 0,
    screenshot_count: 0,
    total_text_length: 0
  }
};

for (const doc of documents) {
  const item = {
    id: doc.id,
    file_name: doc.file_name,
    file_type: doc.file_type,
    mime: doc.mime,

    source_url: doc.source_url,
    storage_url: doc.storage_url,
    storage_bucket: doc.storage_bucket,
    storage_path: doc.storage_path,

    notion_document_page_id: doc.notion_document_page_id,
    notion_file_upload_id: doc.notion_file_upload_id,
    upload_status: doc.upload_status,

    processing_status: doc.processing_status,
    text: doc.extracted_text || "",
    text_length: Number(doc.text_length || 0)
  };

  context.document_index.push({
    file_name: item.file_name,
    file_type: item.file_type,
    mime: item.mime,
    text_length: item.text_length,
    processing_status: item.processing_status,
    upload_status: item.upload_status,
    notion_document_page_id: item.notion_document_page_id,
    storage_path: item.storage_path
  });

  context.stats.total_text_length += item.text_length;

  if (doc.file_type === "sop") {
    context.sources.sop.push(item);
    context.stats.sop_count++;
  } else if (doc.file_type === "documentation") {
    context.sources.documentation.push(item);
    context.stats.documentation_count++;
  } else if (doc.file_type === "screenshot") {
    context.sources.screenshots.push(item);
    context.stats.screenshot_count++;
  }
}

context.has_files = context.stats.total_files > 0;
context.has_sop = context.stats.sop_count > 0;
context.has_documentation = context.stats.documentation_count > 0;
context.has_screenshots = context.stats.screenshot_count > 0;

return [{ json: context }];

const data = $json;

function limitText(text, max) {
  if (!text) return "";
  text = String(text);
  return text.length > max ? text.slice(0, max) + "\n[TRUNCATED]" : text;
}

data.sources.sop = data.sources.sop.map(doc => ({
  ...doc,
  text: limitText(doc.text, 12000)
}));

data.sources.documentation = data.sources.documentation.map(doc => ({
  ...doc,
  text: limitText(doc.text, 12000)
}));

data.sources.screenshots = data.sources.screenshots.map(doc => ({
  ...doc,
  text: limitText(doc.text, 4000)
}));

data.context_limits = {
  sop_max_chars_per_file: 12000,
  documentation_max_chars_per_file: 12000,
  screenshot_max_chars_per_file: 4000
};

return [{ json: data }];

const context = $('Limit AI Context').first().json;
const saved = $input.first().json;

return [
  {
    json: {
      run_id: saved.run_id,
      intake_page_id: saved.intake_page_id,
      project_page_id: saved.project_page_id,
      status: saved.status,
      normalized_context: context
    }
  }
];
